command:
blender -b outputs/station-reference-views/RVA_Station_Approach.blend -t 8 --python-exit-code 1 --python tools/export_godot_station.py > outputs/east-main-corridor/blender.log 2>&1 || { tail -35 outputs/east-main-corridor/blender.log; exit 1; }
tail -12 outputs/east-main-corridor/blender.log
godot --headless --path godot/station_trial --editor --import > outputs/east-main-corridor/import.log 2>&1
godot --headless --path godot/station_trial --fixed-fps 60 --script res://verify_trial.gd
for preset in Windows Linux; do
  case "$preset" in
    Windows) name=windows/RVA-Night-Shift.exe ;;
    Linux) name=linux/RVA-Night-Shift.x86_64 ;;
  esac
  godot --headless --path godot/station_trial --export-release "$preset" "$PWD/outputs/east-main-corridor/$name" > "outputs/east-main-corridor/export-$preset.log" 2>&1 || { tail -20 "outputs/east-main-corridor/export-$preset.log"; exit 1; }
  echo "PASS: Created westbound $preset release."
done
RVA_TRIAL_APPROACH_SCREENSHOT="$PWD/outputs/east-main-corridor/Near_17th.png" python outputs/east-main-corridor/check_render.py
